import 'dart:async';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:hive_flutter/hive_flutter.dart';
import '../main.dart';
import 'resource_settings.dart';

class DeviceResources {
 static const channel=MethodChannel('pocketdex/system');
 static final ValueNotifier<Map<String,dynamic>> stats=ValueNotifier({});static Timer? _timer;static DateTime? _cpuSince;
 static Future<void> refresh()async{try{stats.value=await channel.invokeMapMethod<String,dynamic>('resourceStats')??{};}catch(_){stats.value={};}}
 static void start(){_timer??=Timer.periodic(Duration(seconds:ResourceSettings.instance.refreshSeconds),(_)=>refresh());if(stats.value.isEmpty)refresh();}
 static void restart(){_timer?.cancel();_timer=Timer.periodic(Duration(seconds:ResourceSettings.instance.refreshSeconds),(_)=>refresh());refresh();}
 static String bytes(dynamic v){if(v is! num)return 'N/A';final n=v.toDouble();const units=['B','KB','MB','GB','TB'];var value=n;var index=0;while(value>=1024&&index<units.length-1){value/=1024;index++;}return '${value.toStringAsFixed(index==0?0:1)} ${units[index]}';}
 static bool get cpuWarn {final v=stats.value['cpuPercent'];if(v is! num){_cpuSince=null;return false;}if(v>(ResourceSettings.instance.get('highCpu') as num? ?? 90)){_cpuSince??=DateTime.now();return DateTime.now().difference(_cpuSince!).inSeconds>=10;}_cpuSince=null;return false;}
 static double? percent(dynamic used,dynamic total){if(used is! num||total is! num||total<=0)return null;return used*100/total;}
}
class ResourceMonitor extends StatelessWidget {const ResourceMonitor({super.key,this.compact=false});final bool compact;
 @override Widget build(BuildContext context){DeviceResources.start();return ValueListenableBuilder<Map<String,dynamic>>(valueListenable:DeviceResources.stats,builder:(context,s,_){final used=s['ramUsed'],total=s['ramTotal'],free=total is num&&used is num?total-used:null;final ram='RAM ${DeviceResources.bytes(used)}/${DeviceResources.bytes(total)}';final cpu=s['cpuPercent'] is num?'CPU ${(s['cpuPercent'] as num).toStringAsFixed(0)}%':'CPU N/A';final battery=s['batteryPercent'] is num?'BAT ${s['batteryPercent']}%':'BAT N/A';final storageFree=s['storageFree'],storageTotal=s['storageTotal'];final storage='Storage ${DeviceResources.bytes(storageFree)} free / ${DeviceResources.bytes(storageTotal)}';final net='Net ${s['networkBytesPerSecond'] is num?'${DeviceResources.bytes(s['networkBytesPerSecond'])}/s':'N/A'}';if(compact)return Text('$ram  $cpu  $battery  · ${ResourceSettings.instance.get('profile')}',style:const TextStyle(color:gold,fontSize:9),maxLines:1,overflow:TextOverflow.ellipsis);final ramPct=DeviceResources.percent(free,total);final storagePct=DeviceResources.percent(storageFree,storageTotal);final batteryPct=s['batteryPercent'] is num?(s['batteryPercent'] as num).toDouble():null;final r=ResourceSettings.instance;final warnRam=ramPct!=null&&ramPct<=(r.get('lowRam') as num);final criticalRam=ramPct!=null&&ramPct<=(r.get('criticalRam') as num);final warnStorage=storagePct!=null&&storagePct<=(r.get('lowStorage') as num);final lowStorage=storagePct!=null&&storagePct<=(r.get('lowStorage') as num);final criticalStorage=storagePct!=null&&storagePct<=(r.get('criticalStorage') as num);final batterySaver=batteryPct!=null&&batteryPct<=(r.get('batterySaver') as num);final batteryCritical=batteryPct!=null&&batteryPct<=(r.get('criticalBattery') as num);return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Wrap(spacing:12,runSpacing:8,children:[Text(ram),Text(free is num&&total is num?'Free ${DeviceResources.bytes(free)} (${(ramPct ?? 0).toStringAsFixed(0)}%)':'Free N/A'),Text(cpu),Text(battery),Text(storage),Text(net)]),if(warnRam)Text('${criticalRam?'CRITICAL - ':''}Low Memory ${(ramPct ?? 0).toStringAsFixed(0)}% left',style:TextStyle(color:criticalRam?Colors.red:gold)),if(warnStorage)Text('${criticalStorage?'CRITICAL - ':''}Low Storage ${(storagePct ?? 0).toStringAsFixed(0)}% free',style:TextStyle(color:criticalStorage?Colors.red:gold)),if(batterySaver)Text('Battery ${batteryCritical?'CRITICAL':'Saver'} ${(batteryPct ?? 0).toStringAsFixed(0)}%',style:TextStyle(color:batteryCritical?Colors.red:gold)),if(DeviceResources.cpuWarn)const Text('High CPU',style:TextStyle(color:Colors.red)),if(lowStorage)TextButton(onPressed:(){Hive.box('pocketdex_notes').compact();PaintingBinding.instance.imageCache.clear();PaintingBinding.instance.imageCache.clearLiveImages();},child:const Text('Storage Low - Clear XTR-M Cache',style:TextStyle(color:gold)))]);});}
}
